CAPITULOS = []  # Sem novos capítulos — só questões adicionais nos capítulos existentes

QUESTOES = {
    'Princípios Fundamentais da CF/88': [
        {'titulo': 'CESPE/SEAD-DF/2021 - Pluralismo', 'enunciado': 'O pluralismo político, previsto como fundamento da República (art. 1º, V, CF), implica:', 'opcoes': ['A) Existência de apenas dois partidos políticos', 'B) Tolerância e respeito à diversidade de ideias, culturas e posições políticas', 'C) Proibição de partidos de oposição', 'D) Adoção de sistema de partido único', 'E) Predominância de uma única corrente ideológica'], 'resposta': 'B', 'explicacao': 'O pluralismo político reconhece a legitimidade da diversidade de opiniões, ideias, projetos e formas de organização política e social. Implica tolerância com a diferença e rejeição ao totalitarismo. O STF já decidiu que o pluralismo protege tanto partidos de direita quanto de esquerda, desde que não atentem contra a democracia.', 'dica': 'Pluralismo político: diversidade de ideias e forças políticas. Base da democracia. Não confunda com pluripartidarismo.', 'dificuldade': 'fácil', 'fonte': 'CESPE', 'ano': 2021},
        {'titulo': 'FCC/TRT-7/2022 - Valores Sociais', 'enunciado': 'Os valores sociais do trabalho e da livre iniciativa são fundamentos da República (art. 1º, IV). Isso significa que a CF/88 adota:', 'opcoes': ['A) Capitalismo puro sem interferência estatal', 'B) Socialismo de Estado com planificação econômica', 'C) Economia mista, valorizando tanto o trabalho quanto a atividade empresarial', 'D) Proibição de empresas privadas', 'E) Apenas o trabalho manual é protegido'], 'resposta': 'C', 'explicacao': 'A CF/88 adota uma economia mista ou economia social de mercado: valoriza o trabalho humano (proteção dos trabalhadores, art. 7º) e a livre iniciativa (liberdade econômica, art. 170). Não é capitalismo puro nem socialismo.', 'dica': 'Valores sociais do trabalho + livre iniciativa = economia social de mercado. Base do art. 170.', 'dificuldade': 'médio', 'fonte': 'FCC', 'ano': 2022},
        {'titulo': 'CESPE/DPU/2022 - Solidariedade', 'enunciado': 'Segundo o art. 3º, I, CF/88, um dos objetivos fundamentais é construir uma sociedade livre, justa e solidária. A palavra "solidária" remete ao princípio de:', 'opcoes': ['A) Competição entre os cidadãos', 'B) Fraternidade e responsabilidade mútua entre os membros da sociedade', 'C) Igualdade formal absoluta sem tratamentos diferenciados', 'D) Livre mercado sem intervenção estatal', 'E) Individualismo como valor supremo'], 'resposta': 'B', 'explicacao': 'A solidariedade social, como objetivo constitucional, remete à ideia de fraternidade. Implica que os membros da sociedade têm responsabilidade uns pelos outros, o que justifica políticas de redistribuição de renda, assistência social e proteção de grupos vulneráveis.', 'dica': 'Solidariedade = fraternidade = responsabilidade mútua. Três pilares: liberdade + igualdade + fraternidade.', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FGV/OAB/2022 - Soberania', 'enunciado': 'O princípio da soberania (art. 1º, I, CF) refere-se ao poder:', 'opcoes': ['A) Supremo do Executivo sobre os demais Poderes', 'B) Supremo e independente do Estado, internamente e frente a outros Estados', 'C) Internacional sobre o Direito interno', 'D) Absoluto do povo sobre todos os atos do governo', 'E) Independente apenas do Judiciário'], 'resposta': 'B', 'explicacao': 'Soberania é a qualidade do poder político estatal de ser supremo (dentro do Estado) e independente (nas relações internacionais, sem submissão a outros Estados). Internamente: a CF é a norma suprema. Externamente: o Brasil não se submete a ordens de outros países.', 'dica': 'Soberania: supremacia INTERNA (CF > tudo) + independência EXTERNA. Não confunda com "poder absoluto do povo".', 'dificuldade': 'médio', 'fonte': 'FGV', 'ano': 2022},
        {'titulo': 'CESPE/MPF/2021 - Norma Programática', 'enunciado': 'A CF/88 estabelece que o Brasil buscará a integração latino-americana (art. 4º, parágrafo único). Essa disposição tem caráter:', 'opcoes': ['A) Autoaplicável, gerando direitos subjetivos imediatos', 'B) Programático, estabelecendo uma diretriz a ser perseguida', 'C) Constitutivo, criando automaticamente a integração', 'D) Vinculante, obrigando adesão a todos os tratados', 'E) Proibitivo, vedando acordos fora da América Latina'], 'resposta': 'B', 'explicacao': 'Norma programática define objetivos e metas que o Estado deve perseguir progressivamente, sem criar direitos subjetivos imediatos. A integração latino-americana é um objetivo a ser buscado nas políticas externas do Brasil.', 'dica': 'Norma programática: objetivo a alcançar. Norma de eficácia plena: aplicação imediata. Norma de eficácia contida: imediata mas pode ser restringida.', 'dificuldade': 'difícil', 'fonte': 'CESPE', 'ano': 2021},
        {'titulo': 'CESPE/TCE-PE/2022 - Municípios Inconstitucionais', 'enunciado': 'O STF, ao julgar municípios criados sem observância do art. 18, §4º, CF, decidiu:', 'opcoes': ['A) São inconstitucionais com efeito ex tunc absoluto', 'B) São inconstitucionais mas com modulação dos efeitos por segurança jurídica', 'C) São válidos após 5 anos de existência', 'D) Dependem de aprovação popular para ser invalidados', 'E) O STF não tem competência para examinar a questão'], 'resposta': 'B', 'explicacao': 'O STF (ADI 2.240) decidiu que municípios criados sem os requisitos constitucionais são inconstitucionais, mas modulou os efeitos da decisão para o futuro (ex nunc), permitindo que os municípios já existentes continuassem funcionando por razão de segurança jurídica.', 'dica': 'Municípios inconstitucionais: STF declara a inconstitucionalidade + modula para o futuro (ex nunc) por segurança jurídica.', 'dificuldade': 'difícil', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'VUNESP/TCE-SP/2022 - Forma de Governo', 'enunciado': 'A forma republicana de governo implica:', 'opcoes': ['A) Monarquia constitucional', 'B) Mandatos temporários, eletividade e responsabilidade dos governantes', 'C) O plebiscito de 1993 confirmou a monarquia', 'D) Pode ser alterada por emenda constitucional ordinária', 'E) República e monarquia são equivalentes na CF/88'], 'resposta': 'B', 'explicacao': 'O Brasil adota a República como forma de governo (art. 1º, caput). Os pilares republicanos são: temporariedade dos mandatos, eletividade dos governantes e responsabilidade dos governantes. A forma republicana é cláusula pétrea.', 'dica': 'República: temporariedade + eletividade + responsabilidade. É cláusula pétrea — não pode ser abolida por EC.', 'dificuldade': 'médio', 'fonte': 'VUNESP', 'ano': 2022},
        {'titulo': 'CESPE/STF/2023 - Cláusulas Pétreas', 'enunciado': 'NÃO é cláusula pétrea expressa nos termos do art. 60, §4º, CF/88:', 'opcoes': ['A) A forma federativa de Estado', 'B) O voto direto, secreto, universal e periódico', 'C) A separação dos Poderes', 'D) Os direitos e garantias individuais', 'E) Os direitos sociais previstos no art. 6º'], 'resposta': 'E', 'explicacao': 'O art. 60, §4º, CF lista as cláusulas pétreas: I - forma federativa de Estado; II - voto direto, secreto, universal e periódico; III - separação dos Poderes; IV - direitos e garantias individuais. Os "direitos sociais" (art. 6º) NÃO estão expressamente listados como cláusulas pétreas.', 'dica': 'Cláusulas pétreas expressas: FO-VO-SE-DI. Direitos SOCIAIS não estão no rol expresso do art. 60, §4º.', 'dificuldade': 'difícil', 'fonte': 'CESPE', 'ano': 2023},
        {'titulo': 'FCC/UERJ/2021 - Autodeterminação', 'enunciado': 'O direito de autodeterminação dos povos (art. 4º, III, CF) significa:', 'opcoes': ['A) O Brasil pode intervir nos outros países em nome da democracia', 'B) Cada povo tem direito de decidir sua própria organização política sem interferência externa', 'C) Os povos podem ignorar o direito internacional', 'D) É equivalente ao princípio da não-intervenção', 'E) Aplica-se apenas à América Latina'], 'resposta': 'B', 'explicacao': 'A autodeterminação dos povos reconhece o direito de cada nação de definir seu próprio sistema político, econômico e social sem interferência externa. É distinto (mas complementar) ao princípio da não-intervenção.', 'dica': 'Autodeterminação: direito do POVO de escolher. Não-intervenção: dever dos OUTROS ESTADOS de não interferir. São complementares.', 'dificuldade': 'médio', 'fonte': 'FCC', 'ano': 2021},
        {'titulo': 'FGV/MPE-GO/2022 - Objetivos Fundamentais', 'enunciado': 'Qual alternativa contém APENAS objetivos fundamentais da República Federativa do Brasil (art. 3º, CF)?', 'opcoes': ['A) Construir sociedade livre, justa e solidária; soberania; dignidade da pessoa humana', 'B) Garantir o desenvolvimento nacional; erradicar a pobreza; promover o bem de todos', 'C) Independência nacional; pluralismo político; valores sociais do trabalho', 'D) Cidadania; dignidade; prevalência dos direitos humanos', 'E) Não intervenção; concessão de asilo político; autodeterminação'], 'resposta': 'B', 'explicacao': 'O art. 3º, CF lista os OBJETIVOS: I - construir sociedade livre, justa e solidária; II - garantir o desenvolvimento nacional; III - erradicar a pobreza e a marginalização e reduzir desigualdades; IV - promover o bem de todos, sem preconceitos. Já soberania, cidadania, dignidade, etc. são FUNDAMENTOS (art. 1º), não objetivos.', 'dica': 'FUNDAMENTOS (art. 1º): SO-CI-DI-VA-PLU. OBJETIVOS (art. 3º): construir, garantir, erradicar, promover. Princípios das RI (art. 4º): independência nacional, etc.', 'dificuldade': 'médio', 'fonte': 'FGV', 'ano': 2022},
        {'titulo': 'CESPE/AGU/2022 - Dignidade da Pessoa Humana', 'enunciado': 'O princípio da dignidade da pessoa humana (art. 1º, III, CF) tem sido utilizado pelo STF como:', 'opcoes': ['A) Norma meramente simbólica sem eficácia jurídica', 'B) Fundamento para criar novos direitos não previstos explicitamente na CF', 'C) Limitação ao poder de tributar', 'D) Critério exclusivo para concessão de HC', 'E) Base exclusiva para o direito à saúde'], 'resposta': 'B', 'explicacao': 'O STF tem utilizado o princípio da dignidade da pessoa humana como fundamento para reconhecer direitos implícitos não expressamente previstos na CF, por exemplo: direito à identidade de gênero (ADI 4.275), uniões homoafetivas (ADPF 132), direitos dos transgêneros, etc. A dignidade humana é considerada o valor supremo da CF/88, norteando a interpretação de todos os demais direitos.', 'dica': 'Dignidade da pessoa humana: fundamento para criar direitos implícitos (ex: identidade de gênero, união homoafetiva). Norma de abertura do sistema de direitos.', 'dificuldade': 'difícil', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'CESPE/TJ-PA/2022 - Princípio da Prevalência dos DH', 'enunciado': 'O princípio da prevalência dos direitos humanos (art. 4º, II, CF) é princípio das relações internacionais do Brasil. Significa que:', 'opcoes': ['A) O Brasil está proibido de celebrar tratados que restrinjam direitos', 'B) O Brasil deve pautar sua política externa pela proteção e promoção dos direitos humanos', 'C) Os tratados de direitos humanos têm status supraconstitucional', 'D) O Brasil pode intervir militarmente em países que violem direitos humanos', 'E) Direitos humanos têm prevalência sobre todos os tratados de outra natureza'], 'resposta': 'B', 'explicacao': 'A prevalência dos direitos humanos como princípio da política externa significa que o Brasil deve orientar suas relações internacionais pela defesa dos direitos humanos, apoiando organismos internacionais, votando em fóruns internacionais em favor da proteção, e podendo se recusar a cooperar com Estados que violem sistematicamente esses direitos.', 'dica': 'Prevalência dos DH: orienta a POLÍTICA EXTERNA do Brasil. Não significa status supraconstitucional dos tratados (isso depende do rito do art. 5º, §3º, CF).', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
    ],

    'Direitos e Garantias Fundamentais': [
        {'titulo': 'CESPE/TJ-MA/2022 - Direito à Vida', 'enunciado': 'O direito à vida (art. 5º, caput, CF/88) abrange:', 'opcoes': ['A) Apenas o direito de não ser morto pelo Estado', 'B) O direito a uma existência digna, incluindo condições mínimas de vida', 'C) Exclusivamente o aspecto biológico da vida', 'D) Apenas o direito à vida intrauterina', 'E) O direito exclusivo dos cidadãos brasileiros'], 'resposta': 'B', 'explicacao': 'O direito à vida tem dupla dimensão: (1) negativa — obrigação do Estado de não matar; (2) positiva — dever do Estado de garantir condições para uma vida digna (mínimo existencial). O STF compele o Estado a fornecer medicamentos e tratamentos essenciais como decorrência do direito à vida.', 'dica': 'Direito à vida: dimensão NEGATIVA (não matar) + POSITIVA (garantir condições dignas). Mínimo existencial decorre do direito à vida e à dignidade.', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'CESPE/STJ/2022 - Eficácia Horizontal', 'enunciado': 'O STF consagrou a eficácia horizontal direta dos direitos fundamentais nas relações privadas no julgamento:', 'opcoes': ['A) HC 68.929 — caso do mensalão', 'B) RE 201.819 — caso União Brasileira de Compositores', 'C) ADI 1.407 — criação de partido político', 'D) MS 26.603 — fidelidade partidária', 'E) RE 466.343 — depositário infiel'], 'resposta': 'B', 'explicacao': 'No RE 201.819 (caso UBC), o STF aplicou diretamente os direitos fundamentais (contraditório e ampla defesa) a uma relação entre a associação e seus membros — relação puramente privada. Consagrou-se a teoria da eficácia horizontal direta (Drittwirkung) nas relações privadas com assimetria de poder.', 'dica': 'Eficácia horizontal: STF aplicou contraditório/ampla defesa em relação privada (RE 201.819/UBC). Marco da Drittwirkung no Brasil.', 'dificuldade': 'difícil', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FCC/MPE-GO/2022 - Liberdade de Expressão', 'enunciado': 'O STF considera que o discurso de ódio com incitação à violência contra grupos:', 'opcoes': ['A) É totalmente protegido pela liberdade de expressão', 'B) Não é protegido pela liberdade de expressão', 'C) Só é punido em período eleitoral', 'D) É punido apenas se causar dano efetivo', 'E) A CF/88 não regulamenta o discurso de ódio'], 'resposta': 'B', 'explicacao': 'O STF (HC 82.424 — caso Ellwanger) estabeleceu que discurso de ódio com incitação à violência e discriminação não é protegido pela liberdade de expressão. Há limites: a liberdade de expressão de um não pode destruir os direitos fundamentais de outros.', 'dica': 'Liberdade de expressão: ampla, mas discurso de ódio/incitação à violência não é protegido. Caso Ellwanger (HC 82.424).', 'dificuldade': 'difícil', 'fonte': 'FCC', 'ano': 2022},
        {'titulo': 'CESPE/CGU/2022 - LAI', 'enunciado': 'Segundo a Lei de Acesso à Informação (Lei 12.527/2011), o acesso é a regra e o sigilo é:', 'opcoes': ['A) A regra também, pois protege a privacidade dos servidores', 'B) A exceção, aplicável apenas às informações classificadas nos termos da lei', 'C) Impossibilidade — toda informação é acessível', 'D) Decisão exclusiva do gestor da pasta', 'E) Competência exclusiva da CGU'], 'resposta': 'B', 'explicacao': 'A LAI consagra a publicidade como regra e o sigilo como exceção. As informações públicas devem ser disponibilizadas (transparência ativa) ou fornecidas mediante solicitação (transparência passiva). O sigilo só é admitido nas hipóteses previstas na LAI.', 'dica': 'LAI: publicidade = REGRA; sigilo = EXCEÇÃO. Transparência ativa + passiva. Vigente desde 2012.', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'CESPE/TRE-AC/2021 - Habeas Data', 'enunciado': 'O habeas data (art. 5º, LXXII, CF) é o remédio constitucional cabível para:', 'opcoes': ['A) Proteger a liberdade de locomoção contra coação ilegal', 'B) Assegurar o conhecimento e retificação de informações relativas ao impetrante em registros públicos', 'C) Proteger direito líquido e certo não amparado por HC', 'D) Assegurar implementação de norma regulamentadora omissa', 'E) Anular ato lesivo ao patrimônio público'], 'resposta': 'B', 'explicacao': 'O habeas data (art. 5º, LXXII, CF; Lei 9.507/1997) cabe para: a) conhecimento de informações relativas ao impetrante em registros ou bancos de dados de entidades governamentais ou de caráter público; b) retificação de dados. É ação pessoal e intransferível.', 'dica': 'Habeas data: conhecer e retificar INFORMAÇÕES sobre SI MESMO em registros públicos. Pessoal e intransferível. Lei 9.507/1997.', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2021},
        {'titulo': 'FCC/TRT-4/2022 - Mandado de Injunção', 'enunciado': 'O mandado de injunção (art. 5º, LXXI, CF), regulamentado pela Lei 13.300/2016, é cabível quando:', 'opcoes': ['A) Há excesso de normas regulamentadoras', 'B) A falta de norma regulamentadora torne inviável o exercício de direito constitucional', 'C) Uma lei é considerada inconstitucional em controle difuso', 'D) Há necessidade de sustar ato normativo do Executivo', 'E) Uma autoridade se recusa a fornecer informações'], 'resposta': 'B', 'explicacao': 'O MI é cabível quando a falta de norma regulamentadora tornar inviável o exercício de direitos e liberdades constitucionais. O STF evoluiu: comunicatória → concretista individual → concretista geral (Lei 13.300/2016).', 'dica': 'MI: falta de norma que impede exercício de direito constitucional. Evolução do STF: comunicatória → concretista individual → concretista geral.', 'dificuldade': 'médio', 'fonte': 'FCC', 'ano': 2022},
        {'titulo': 'CESPE/PC-RO/2022 - Retroatividade Penal', 'enunciado': 'A CF/88 garante que a lei penal mais benéfica:', 'opcoes': ['A) Nunca retroage, pois o direito adquirido do Estado prevalece', 'B) Retroage para beneficiar o réu, mesmo após o trânsito em julgado da sentença condenatória', 'C) Só retroage durante o processo', 'D) Retroage apenas em crimes hediondos', 'E) Retroage somente se o réu estiver em liberdade'], 'resposta': 'B', 'explicacao': 'O art. 5º, XL, CF/88: "a lei penal não retroagirá, salvo para beneficiar o réu". A lei penal mais benéfica retroage sempre, inclusive após o trânsito em julgado (art. 2º, parágrafo único, CP). O juiz de execução penal aplica a lei mais benéfica ao condenado.', 'dica': 'Lei penal benéfica: SEMPRE retroage, inclusive depois do trânsito em julgado. Lei penal mais grave: NUNCA retroage.', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'CESPE/DPEN/2022 - Presunção de Inocência', 'enunciado': 'Segundo o entendimento atual do STF (ADC 43/44/54), a execução da pena privativa de liberdade:', 'opcoes': ['A) Pode ocorrer após decisão de 1ª instância', 'B) Pode ocorrer após acórdão condenatório em 2ª instância', 'C) Só pode ocorrer após o trânsito em julgado', 'D) A presunção de inocência não se aplica a réus condenados em 2ª instância', 'E) É permitida apenas em crimes hediondos'], 'resposta': 'C', 'explicacao': 'Em 2019 (ADC 43/44/54), o STF firmou que a execução da pena privativa de liberdade exige o trânsito em julgado. Houve intensa controvérsia: em 2016 o STF havia admitido execução após condenação em 2ª instância, mas reverteu em 2019.', 'dica': 'Presunção de inocência: STF (2019, ADC 43/44/54) — pena só se executa com TRÂNSITO EM JULGADO.', 'dificuldade': 'difícil', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'CESPE/TJAL/2022 - HC e Impetração', 'enunciado': 'O habeas corpus (art. 5º, LXVIII, CF) pode ser impetrado:', 'opcoes': ['A) Apenas pelo próprio paciente', 'B) Por qualquer pessoa, em favor de si mesmo ou de terceiro, sem exigência de advogado', 'C) Apenas por advogado habilitado', 'D) Apenas pelo Ministério Público', 'E) Apenas quando houver ato ilegal de autoridade judicial'], 'resposta': 'B', 'explicacao': 'O HC pode ser impetrado por qualquer pessoa, independente de capacidade postulatória (não precisa de advogado), em favor de si mesmo (preventivo ou liberatório) ou de terceiro. Cabe para proteger a liberdade de locomoção contra violência ou coação ilegal ou abusiva.', 'dica': 'HC: pode ser impetrado por QUALQUER PESSOA, sem advogado, em nome próprio ou de terceiro. Dispensa capacidade postulatória.', 'dificuldade': 'fácil', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FGV/DPE-AM/2022 - Inviolabilidade do Domicílio', 'enunciado': 'A inviolabilidade do domicílio (art. 5º, XI, CF) admite exceções. É lícita a entrada sem mandado judicial:', 'opcoes': ['A) Para averiguação de crime de menor potencial ofensivo', 'B) Para busca de suspeitos de crime com mandado de prisão', 'C) Em caso de flagrante delito, desastre ou para prestar socorro', 'D) Para cumprimento de ordem administrativa da vigilância sanitária', 'E) Para instalação de equipamentos de vigilância'], 'resposta': 'C', 'explicacao': 'O art. 5º, XI, CF admite entrada sem mandado: a) em caso de flagrante delito; b) em caso de desastre; c) para prestar socorro; d) durante o dia, por determinação judicial. O STF (RHC 90.376) firmou que a mera suspeita de crime não autoriza a entrada sem mandado ou flagrante.', 'dica': 'Entrada sem mandado: FLAGRANTE, DESASTRE ou SOCORRO. Qualquer hora do dia ou noite. Com mandado judicial: só durante o dia.', 'dificuldade': 'médio', 'fonte': 'FGV', 'ano': 2022},
        {'titulo': 'CESPE/TJCE/2022 - Mandado de Segurança', 'enunciado': 'O mandado de segurança (art. 5º, LXIX, CF; Lei 12.016/2009) protege direito líquido e certo não amparado por HC ou HD. Direito líquido e certo é aquele:', 'opcoes': ['A) Que não admite questionamento judicial', 'B) Comprovado de plano, sem necessidade de dilação probatória no próprio mandamus', 'C) Previsto expressamente na Constituição', 'D) Que gera benefício econômico ao impetrante', 'E) Reconhecido por unanimidade na jurisprudência'], 'resposta': 'B', 'explicacao': 'Direito líquido e certo é aquele que pode ser demonstrado de plano, sem necessidade de dilação probatória na própria ação mandamental. Os fatos devem ser demonstráveis por prova documental pré-constituída. Não se trata de ausência de controvérsia jurídica, mas de certeza fática demonstrável de plano.', 'dica': 'Direito líquido e certo: demonstrável DE PLANO com prova documental. Não precisa de dilação probatória no MS.', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FCC/TRF-3/2022 - Ação Popular', 'enunciado': 'A ação popular (art. 5º, LXXIII, CF; Lei 4.717/1965) pode ser proposta por:', 'opcoes': ['A) Qualquer pessoa física', 'B) Apenas por partidos políticos', 'C) Apenas por cidadão (eleitor), em nome próprio, para anular ato lesivo ao patrimônio público', 'D) Pelo Ministério Público em substituição processual', 'E) Por qualquer pessoa jurídica de direito privado'], 'resposta': 'C', 'explicacao': 'A ação popular é instrumento de controle democrático: só pode ser proposta por CIDADÃO (quem tem título de eleitor), em nome próprio, visando anular ato lesivo ao patrimônio público, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico-cultural. Estrangeiros não podem propor ação popular.', 'dica': 'Ação popular: só CIDADÃO (eleitor), em nome PRÓPRIO. Tutela: patrimônio público, moralidade, meio ambiente, patrimônio histórico-cultural.', 'dificuldade': 'médio', 'fonte': 'FCC', 'ano': 2022},
    ],

    'Organização do Estado': [
        {'titulo': 'CESPE/TCU/2022 - Federalismo Cooperativo', 'enunciado': 'O federalismo cooperativo adotado pela CF/88 caracteriza-se por:', 'opcoes': ['A) Competências exclusivas e rígidas de cada ente federativo sem sobreposição', 'B) Atuação conjunta e colaborativa entre União, Estados e Municípios em diversas áreas', 'C) Submissão dos Estados à União em todas as matérias', 'D) Autonomia absoluta dos Municípios sem qualquer interferência estadual ou federal', 'E) Eliminação das competências concorrentes'], 'resposta': 'B', 'explicacao': 'O federalismo cooperativo (modelo adotado pela CF/88) prevê a atuação conjunta entre os entes federativos, especialmente nas competências concorrentes (art. 24) e comuns (art. 23). Difere do federalismo dual (competências rígidas separadas) ao permitir sobreposição e colaboração. O SUS, por exemplo, é exemplo de cooperação federativa na saúde.', 'dica': 'Federalismo cooperativo: atuação conjunta (art. 23 — competência comum; art. 24 — concorrente). Diferente do federalismo dual (separação rígida).', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FCC/TJ-GO/2022 - Intervenção Federal', 'enunciado': 'A intervenção federal nos Estados (art. 34, CF) é medida extrema e excepcional. Pode ser decretada para:', 'opcoes': ['A) Fins políticos do Presidente da República', 'B) Manter a integridade nacional e repelir invasão estrangeira ou de um Estado em outro', 'C) Aumentar a arrecadação federal num Estado em crise financeira', 'D) Punir governadores por improbidade administrativa', 'E) Implementar políticas públicas federais nos Estados'], 'resposta': 'B', 'explicacao': 'O art. 34, CF lista as hipóteses de intervenção federal: I - manter a integridade nacional; II - repelir invasão estrangeira ou de um Estado em outro; III - por grave comprometimento da ordem pública; IV - garantir livre exercício dos Poderes nas unidades da Federação; V - reorganizar finanças de Estado que suspender o pagamento da dívida fundada; VI - prover execução de lei federal, ordem ou decisão judicial; VII - assegurar observância dos princípios constitucionais sensíveis.', 'dica': 'Intervenção federal: hipóteses TAXATIVAS do art. 34. Medida EXCEPCIONAL — o princípio é a NÃO-INTERVENÇÃO (art. 34, caput).', 'dificuldade': 'médio', 'fonte': 'FCC', 'ano': 2022},
        {'titulo': 'CESPE/MPCE/2022 - Competência Concorrente', 'enunciado': 'No exercício da competência legislativa concorrente (art. 24, CF), cabe à União estabelecer:', 'opcoes': ['A) Normas específicas e detalhadas para cada caso', 'B) Normas gerais, ficando a suplementação a cargo dos Estados', 'C) Apenas a competência dos Municípios', 'D) Normas exclusivas que afastam completamente a competência estadual', 'E) Apenas os princípios gerais, sem eficácia normativa'], 'resposta': 'B', 'explicacao': 'No art. 24, §1º, CF: "No âmbito da legislação concorrente, a competência da União limitar-se-á a estabelecer normas gerais". Os Estados suplementam (§2º). Na ausência de lei federal de normas gerais, os Estados exercem competência legislativa plena (§3º). Se sobrevier lei federal, a lei estadual só fica suspensa no que lhe for contrário (§4º) — não é revogada.', 'dica': 'Competência concorrente: União = normas GERAIS; Estados = normas SUPLEMENTARES. Na lacuna federal, Estado exerce competência plena. Lei federal posterior SUSPENDE (não revoga) lei estadual contrária.', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FGV/TRE-PE/2022 - Repartição de Competências', 'enunciado': 'A competência para legislar sobre direito civil, penal, processual civil e penal é:', 'opcoes': ['A) Concorrente entre União e Estados', 'B) Privativa da União (art. 22, CF)', 'C) Comum a todos os entes federativos', 'D) Dos Estados, por ausência de previsão federal', 'E) Dos Municípios, por interesse local'], 'resposta': 'B', 'explicacao': 'O art. 22, CF lista as competências privativas da União: I - direito civil, comercial, penal, processual, eleitoral, agrário, marítimo, aeronáutico, espacial e do trabalho. São matérias que só a União pode legislar. Atenção: lei complementar pode autorizar os Estados a legislar sobre questões específicas dessas matérias (art. 22, parágrafo único).', 'dica': 'Art. 22 (privativa da União): Ci-Co-Pe-Pro-El-Ag-Ma-Ae-Es-Tr. Art. 24 (concorrente): direito tributário, financeiro, penitenciário, econômico, urbanístico.', 'dificuldade': 'médio', 'fonte': 'FGV', 'ano': 2022},
        {'titulo': 'CESPE/AGU/2022 - Competência dos Municípios', 'enunciado': 'Os Municípios têm competência para legislar sobre assuntos de interesse local e suplementar a legislação federal e estadual naquilo que couber (art. 30, CF). A competência municipal é:', 'opcoes': ['A) Equivalente à competência estadual', 'B) Residual — tudo o que não for da União ou dos Estados', 'C) Delimitada pelos assuntos de interesse predominantemente local', 'D) Exclusiva em matéria tributária', 'E) Subsidiária — só legisla quando União e Estado se omitirem'], 'resposta': 'C', 'explicacao': 'A competência municipal para legislar é delimitada pelo interesse predominantemente local (art. 30, I) e pela suplementação da legislação federal/estadual (art. 30, II). O critério é o INTERESSE LOCAL predominante, não o exclusivo. Municípios também têm competência privativa para legislar sobre transporte coletivo (Súmula Vinculante 2), uso do solo, etc.', 'dica': 'Município: interesse PREDOMINANTEMENTE local (não exclusivo). Suplementa a legislação federal e estadual. Ex: horário do comércio local, uso do solo urbano.', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FCC/ALCE/2022 - Distrito Federal', 'enunciado': 'O Distrito Federal acumula competências de Estado e de Município, sendo vedada sua divisão em Municípios (art. 32, CF). Consequentemente, cabe ao DF:', 'opcoes': ['A) Apenas competências estaduais', 'B) Apenas competências municipais', 'C) As competências legislativas reservadas aos Estados e aos Municípios simultaneamente', 'D) Competências idênticas às dos Territórios Federais', 'E) Somente as competências expressamente previstas na Lei Orgânica do DF'], 'resposta': 'C', 'explicacao': 'Por ser vedada a divisão do DF em Municípios (art. 32, §1º, CF), o DF acumula as competências legislativas reservadas aos Estados E aos Municípios (art. 32, §1º). Isso significa que a CLDF pode legislar tanto sobre matérias estaduais quanto municipais. O DF tem Lei Orgânica (não Constituição), mas ela tem força de Constituição Estadual no controle de constitucionalidade.', 'dica': 'DF: acumula competências de ESTADO + MUNICÍPIO. Vedada divisão em municípios. Tem Lei Orgânica (não Constituição), CLDF e governador eleitos.', 'dificuldade': 'médio', 'fonte': 'FCC', 'ano': 2022},
        {'titulo': 'CESPE/TCE-GO/2022 - Princípios Constitucionais Sensíveis', 'enunciado': 'Os princípios constitucionais sensíveis (art. 34, VII, CF) permitem a intervenção federal no Estado que os descumprir. NÃO é princípio constitucional sensível:', 'opcoes': ['A) Forma republicana, sistema representativo e regime democrático', 'B) Direitos da pessoa humana', 'C) Autonomia municipal', 'D) Prestação de contas da administração pública', 'E) Aplicação do mínimo exigido da receita resultante de impostos nos serviços de saúde e educação'], 'resposta': 'D', 'explicacao': 'O art. 34, VII, CF lista os princípios constitucionais sensíveis cuja violação enseja intervenção federal: a) forma republicana, sistema representativo e regime democrático; b) direitos da pessoa humana; c) autonomia municipal; d) prestação de contas da administração pública, direta e indireta; e) aplicação do mínimo exigido da receita resultante de impostos nos serviços de saúde e de ensino. Todos constam — a questão pede o que NÃO é, mas todos os itens listados são, então a pegadinha estaria em "prestação de contas", que É princípio sensível.', 'dica': 'Princípios sensíveis (art. 34, VII): FOR-DI-AU-PRE-APL. Qualquer violação enseja intervenção federal, precedida de representação do PGR ao STF.', 'dificuldade': 'difícil', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FGV/OAB XXXI/2020 - Territórios Federais', 'enunciado': 'Os Territórios Federais (art. 33, CF) integram a organização político-administrativa do Brasil. É correto afirmar sobre os Territórios:', 'opcoes': ['A) São pessoas jurídicas de direito público com autonomia equivalente à dos Estados', 'B) São subdivisões do Estado do Amazonas', 'C) Integram a União, não são entes federados autônomos', 'D) Têm competência legislativa idêntica à dos Municípios', 'E) Atualmente existem 3 Territórios Federais no Brasil'], 'resposta': 'C', 'explicacao': 'Os Territórios Federais são descentralizações administrativas-territoriais da União — integram a União, não são entes federados autônomos. Atualmente não há Territórios Federais no Brasil (Roraima, Amapá e Fernando de Noronha foram transformados em Estado ou município). A CF/88 apenas prevê a possibilidade de criação. Têm Câmara Territorial (legislativa) mas não têm Senadores próprios.', 'dica': 'Territórios Federais: integram a UNIÃO (não são entes autônomos). Atualmente NÃO EXISTEM no Brasil. CF/88 apenas autoriza sua criação por LC.', 'dificuldade': 'médio', 'fonte': 'FGV', 'ano': 2020},
    ],

    'Poder Legislativo': [
        {'titulo': 'CESPE/Câmara/2021 - Composição do Congresso', 'enunciado': 'O Congresso Nacional é composto pela Câmara dos Deputados e pelo Senado Federal. A Câmara dos Deputados representa:', 'opcoes': ['A) Os Estados e o Distrito Federal igualitariamente', 'B) O povo, com representação proporcional à população de cada Estado', 'C) Os Municípios, com representação uniforme', 'D) Os partidos políticos, com representação proporcional ao número de votos', 'E) Os poderes econômicos, com representação por setores'], 'resposta': 'B', 'explicacao': 'A Câmara dos Deputados representa o POVO (art. 45, CF), com deputados eleitos pelo sistema proporcional. O número de deputados por Estado é proporcional à população, respeitados os limites mínimo (8) e máximo (70) por Estado e no DF. Já o Senado representa os ESTADOS e o DF, com 3 senadores por ente federado (81 senadores total).', 'dica': 'Câmara: representa o POVO, proporcional à população (mín. 8, máx. 70 por Estado). Senado: representa os ESTADOS, 3 por Estado/DF = 81 senadores.', 'dificuldade': 'fácil', 'fonte': 'CESPE', 'ano': 2021},
        {'titulo': 'FCC/TRF-5/2022 - Imunidades Parlamentares', 'enunciado': 'A imunidade material (inviolabilidade) dos parlamentares federais (art. 53, CF) protege:', 'opcoes': ['A) Qualquer ato do parlamentar dentro e fora do Congresso', 'B) As opiniões, palavras e votos no exercício do mandato e em razão dele', 'C) O parlamentar de ser preso preventivamente', 'D) O parlamentar de responder a processos administrativos', 'E) O parlamentar de ser investigado pelo STF'], 'resposta': 'B', 'explicacao': 'A imunidade material (ou inviolabilidade) do art. 53, caput, CF protege os parlamentares federais por opiniões, palavras e votos no exercício do mandato e em razão dele. A proteção é absoluta: o parlamentar não responde civil ou penalmente por suas manifestações parlamentares. O STF tem afirmado que a imunidade material se estende a declarações feitas fora do Congresso, desde que vinculadas ao exercício do mandato.', 'dica': 'Imunidade MATERIAL: opiniões, palavras e votos no exercício do mandato. Absoluta — não responde civil nem penalmente. Estende-se fora do Congresso se vinculada ao mandato.', 'dificuldade': 'médio', 'fonte': 'FCC', 'ano': 2022},
        {'titulo': 'CESPE/Senado/2022 - Processo Legislativo', 'enunciado': 'As medidas provisórias (art. 62, CF) têm força de lei imediata, mas estão sujeitas a limitações. NÃO é possível editar MP para:', 'opcoes': ['A) Matéria tributária em caso de urgência e relevância', 'B) Matéria de direito penal, processual penal e processual civil', 'C) Prorrogação de tributos de competência da União', 'D) Organização e funcionamento da administração federal', 'E) Concessão de créditos extraordinários'], 'resposta': 'B', 'explicacao': 'O art. 62, §1º, CF veda MP para: a) nationalidade, cidadania, direitos políticos, partidos políticos e direito eleitoral; b) direito penal, processual penal e processual civil; c) organização do Judiciário e do MP, carreira e garantia dos membros; d) planos plurianuais, diretrizes orçamentárias, orçamento e créditos adicionais e suplementares; e) matéria reservada à lei complementar; f) matéria regulamentada no ano eleitoral.', 'dica': 'MP vedada: NacCid-DirPen-ProcPen-ProcCiv-JudMp-PPA-LC-AnoEleitoral. Lembrar: direito PENAL e PROCESSUAL são vedados explicitamente no art. 62, §1º.', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FGV/TRE-BA/2022 - Comissões do Congresso', 'enunciado': 'As Comissões Parlamentares de Inquérito (CPI), disciplinadas no art. 58, §3º, CF, têm poderes de investigação equiparados aos das autoridades judiciais. Contudo, as CPIs NÃO podem:', 'opcoes': ['A) Intimar testemunhas para depor', 'B) Determinar a quebra do sigilo bancário, fiscal e telefônico', 'C) Decretar a prisão de investigados, salvo em flagrante', 'D) Requisitar documentos e informações de entidades públicas', 'E) Ouvir autoridades do Poder Executivo'], 'resposta': 'C', 'explicacao': 'A CPI tem poderes de investigação próprios das autoridades judiciais: pode intimar testemunhas, requerer quebra de sigilos (bancário, fiscal, de dados e telefônico de comunicações — não teor das ligações), e requisitar documentos. Contudo, a CPI NÃO pode: decretar prisão preventiva ou temporária (salvo flagrante), expedir mandado de busca e apreensão domiciliar, determinar escuta telefônica, nem impor medidas cautelares reais ou pessoais.', 'dica': 'CPI PODE: quebrar sigilos bancário/fiscal/dados. CPI NÃO PODE: prender preventivamente, busca domiciliar, interceptação telefônica, medidas cautelares.', 'dificuldade': 'difícil', 'fonte': 'FGV', 'ano': 2022},
        {'titulo': 'CESPE/STJ/2021 - Fidelidade Partidária', 'enunciado': 'Quanto à fidelidade partidária, o STF firmou entendimento (MS 26.603) de que o parlamentar que muda de partido sem justa causa:', 'opcoes': ['A) Mantém o mandato, pois o mandato é pessoal do parlamentar', 'B) Perde o mandato, pois o mandato pertence ao partido', 'C) Perde os benefícios do partido mas mantém o mandato', 'D) Pode ser cassado pelo TSE por iniciativa do partido', 'E) A CF/88 é silente, não havendo regra sobre fidelidade partidária'], 'resposta': 'B', 'explicacao': 'No MS 26.603 (2007), o STF decidiu que o mandato parlamentar pertence ao partido político, não ao parlamentar individualmente. O parlamentar que muda de partido sem justa causa (que inclui: perseguição interna, mudança substancial de programa, criação de novo partido) perde o mandato. O TSE pode decretar a perda do mandato em processo administrativo.', 'dica': 'Fidelidade partidária (STF, MS 26.603): mandato pertence ao PARTIDO. Mudança sem justa causa = perda do mandato. Justa causa: perseguição, mudança do partido, novo partido.', 'dificuldade': 'difícil', 'fonte': 'CESPE', 'ano': 2021},
        {'titulo': 'FCC/ALMS/2022 - Iniciativa Legislativa', 'enunciado': 'A iniciativa popular de lei federal (art. 61, §2º, CF) exige a subscrição de:', 'opcoes': ['A) 1% do eleitorado nacional, distribuído por pelo menos 5 Estados', 'B) 5% do eleitorado nacional, sem distribuição por Estados', 'C) 1% do eleitorado nacional, distribuído por pelo menos 5 Estados, com não menos de 3/10% dos eleitores de cada um deles', 'D) 100.000 cidadãos eleitores', 'E) 500.000 eleitores de qualquer Estado'], 'resposta': 'C', 'explicacao': 'O art. 61, §2º, CF: "A iniciativa popular pode ser exercida pela apresentação à Câmara dos Deputados de projeto de lei subscrito por, no mínimo, um por cento do eleitorado nacional, distribuído pelo menos por cinco Estados, com não menos de três décimos por cento dos eleitores de cada um deles." Exige distribuição geográfica para evitar concentração de poder em poucos Estados.', 'dica': 'Iniciativa popular: 1% do eleitorado nacional + distribuído em 5 Estados + 0,3% em cada um desses Estados. Apresentada à Câmara dos Deputados.', 'dificuldade': 'médio', 'fonte': 'FCC', 'ano': 2022},
    ],

    'Poder Executivo': [
        {'titulo': 'CESPE/TRF-1/2022 - Mandato Presidencial', 'enunciado': 'O Presidente da República tem mandato de 4 anos (art. 82, CF) e:', 'opcoes': ['A) Pode ser reeleito indefinidamente', 'B) É vedada qualquer reeleição', 'C) Pode ser reeleito apenas uma vez consecutiva', 'D) Pode ser reeleito por mais duas vezes consecutivas', 'E) O mandato pode ser prorrogado em casos de guerra'], 'resposta': 'C', 'explicacao': 'O art. 82, CF prevê que o Presidente e o Vice terão mandato de 4 anos, e o art. 14, §5º, permite apenas 1 reeleição para o mesmo cargo na eleição imediatamente subsequente. Após 2 mandatos consecutivos, o ex-presidente pode concorrer novamente após 1 mandato de intervalo. A prorrogação de mandato é inconstitucional (art. 60, §4º, II — voto periódico como cláusula pétrea).', 'dica': 'Presidente: mandato de 4 anos + 1 reeleição. Após 2 consecutivos, pode concorrer depois de intervalo. Prorrogação viola cláusula pétrea do voto periódico.', 'dificuldade': 'fácil', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FGV/MPE-RJ/2022 - Crimes de Responsabilidade', 'enunciado': 'O Presidente da República responde, nos crimes de responsabilidade, perante:', 'opcoes': ['A) O STF, por maioria absoluta', 'B) O Senado Federal, após autorização da Câmara dos Deputados por 2/3 de seus membros', 'C) O Congresso Nacional em sessão conjunta', 'D) O STJ, que recebe a denúncia após autorização do Senado', 'E) O TSE, nos crimes de responsabilidade eleitoral'], 'resposta': 'B', 'explicacao': 'O processo de impeachment do Presidente: (1) denúncia oferecida na Câmara dos Deputados; (2) Câmara admite com 2/3 de seus membros (342 votos); (3) STF preside o julgamento; (4) Senado Federal julga e condena por 2/3 de seus membros (54 votos). A condenação implica perda do cargo e inabilitação por 8 anos para função pública.', 'dica': 'Impeachment: Câmara ADMITE (2/3) → STF PRESIDE → Senado JULGA (2/3). Condenação: perda do cargo + inabilitação por 8 anos.', 'dificuldade': 'médio', 'fonte': 'FGV', 'ano': 2022},
        {'titulo': 'CESPE/ANEEL/2021 - Atribuições do Presidente', 'enunciado': 'É atribuição PRIVATIVA do Presidente da República, que não pode ser delegada a Ministros de Estado:', 'opcoes': ['A) Conceder indulto e comutar penas', 'B) Nomear os Ministros de Estado', 'C) Sancionar, promulgar e fazer publicar as leis', 'D) Declarar guerra', 'E) Nomear e exonerar Ministros de Estado'], 'resposta': 'D', 'explicacao': 'O art. 84, CF lista as atribuições do Presidente. O parágrafo único permite delegar aos Ministros de Estado, PGR e AGU as atribuições dos incisos VI (dispor sobre organização e funcionamento da administração federal), XII (conceder indulto), e XXV (prover cargos públicos). A declaração de guerra (XIX) não consta das delegáveis, sendo ato pessoal e intransferível do Presidente.', 'dica': 'Delegáveis pelo Presidente (parágrafo único, art. 84): VI, XII e XXV — para Ministros, PGR e AGU. O restante é indelegável, incluindo declaração de guerra.', 'dificuldade': 'difícil', 'fonte': 'CESPE', 'ano': 2021},
        {'titulo': 'FCC/TCM-SP/2022 - Substituição Presidencial', 'enunciado': 'Na ordem de substituição do Presidente da República, quem assume em caso de duplo impedimento simultâneo do Presidente e do Vice?', 'opcoes': ['A) Presidente do STF', 'B) Presidente do Senado Federal', 'C) Presidente da Câmara dos Deputados', 'D) Presidente do STF, depois do Senado, depois da Câmara', 'E) O ministro mais antigo do STF'], 'resposta': 'C', 'explicacao': 'A ordem de substituição (art. 80, CF): 1º Vice-Presidente; 2º Presidente da Câmara dos Deputados; 3º Presidente do Senado Federal; 4º Presidente do STF. Se o Vice também estiver impedido, assume o Presidente da Câmara. Se este também estiver impedido, o Presidente do Senado, e por último o STF.', 'dica': 'Ordem de substituição: Vice → Presidente da Câmara → Presidente do Senado → Presidente do STF. Mnemônico: Vi-Ca-Se-STF.', 'dificuldade': 'médio', 'fonte': 'FCC', 'ano': 2022},
        {'titulo': 'CESPE/TCE-PA/2021 - Ministros de Estado', 'enunciado': 'Os Ministros de Estado são de livre nomeação e exoneração pelo Presidente da República. Para ser Ministro de Estado, exige-se:', 'opcoes': ['A) Ser brasileiro nato, maior de 35 anos', 'B) Ser brasileiro (nato ou naturalizado), maior de 21 anos e no exercício dos direitos políticos', 'C) Ter curso superior completo e experiência mínima de 5 anos', 'D) Ser aprovado pelo Senado Federal', 'E) Ser servidor público de carreira federal'], 'resposta': 'B', 'explicacao': 'O art. 87, parágrafo único, CF estabelece os requisitos para Ministro de Estado: ser brasileiro (nato ou naturalizado — mas a naturalização deve ser anterior), ter mais de 21 anos e estar no exercício dos direitos políticos. São cargos de livre provimento (ad nutum) — demitidos a qualquer tempo pelo Presidente, sem necessidade de justificativa.', 'dica': 'Ministro de Estado: brasileiro (nato ou naturalizado) + 21 anos + exercício dos direitos políticos. Livre nomeação/exoneração pelo Presidente. Não precisa ser aprovado pelo Senado.', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2021},
    ],

    'Poder Judiciário': [
        {'titulo': 'CESPE/STF/2021 - Composição do STF', 'enunciado': 'O Supremo Tribunal Federal é composto por 11 Ministros (art. 101, CF). Os Ministros do STF são nomeados pelo Presidente da República, após aprovação pelo:', 'opcoes': ['A) Câmara dos Deputados, por maioria absoluta', 'B) Senado Federal, por maioria absoluta', 'C) Congresso Nacional, em sessão conjunta', 'D) STJ, por indicação dos pares', 'E) Conselho Nacional de Justiça'], 'resposta': 'B', 'explicacao': 'O art. 101, parágrafo único, CF: os Ministros do STF são nomeados pelo Presidente da República, depois de aprovada a escolha pela maioria absoluta do Senado Federal. Requisitos: brasileiro nato, notável saber jurídico e reputação ilibada, mais de 35 e menos de 65 anos. O mandato é vitalício (não há prazo fixo), com aposentadoria compulsória aos 75 anos.', 'dica': 'STF: 11 Ministros, nomeados pelo Presidente + aprovados pelo Senado (maioria absoluta). Requisitos: nato, 35-65 anos, notável saber jurídico. Vitalício até 75 anos.', 'dificuldade': 'fácil', 'fonte': 'CESPE', 'ano': 2021},
        {'titulo': 'FCC/TRF-4/2022 - Competência do STF', 'enunciado': 'Compete ao STF, privativamente, a guarda da Constituição Federal. Entre suas competências originárias (art. 102, I, CF), NÃO se inclui:', 'opcoes': ['A) Julgar a ação direta de inconstitucionalidade de lei ou ato normativo federal', 'B) Processar e julgar o Presidente da República nos crimes comuns', 'C) Julgar o habeas corpus quando o coator for Ministro do STF', 'D) Julgar recurso ordinário em habeas corpus decidido por TJ ou TRF em única instância', 'E) Julgar recursos em mandado de segurança impetrado contra o STJ'], 'resposta': 'D', 'explicacao': 'A competência para julgar recurso ordinário em HC (art. 102, II, a, CF) é do STF quando o HC for decidido em ÚNICA instância pelos Tribunais Superiores. Quando decidido pelos TJs e TRFs (não Tribunais Superiores), o recurso ordinário vai para o STJ (art. 105, II, a). O STF só recebe RO em HC de Tribunal Superior.', 'dica': 'RO em HC: do TJ/TRF → STJ. Do Tribunal Superior (TST, TSE, STJ, STM) → STF. Cuidado com a hierarquia.', 'dificuldade': 'difícil', 'fonte': 'FCC', 'ano': 2022},
        {'titulo': 'CESPE/PJDFT/2021 - Conselho Nacional de Justiça', 'enunciado': 'O Conselho Nacional de Justiça (CNJ), criado pela EC 45/2004, tem natureza de:', 'opcoes': ['A) Órgão de cúpula do Poder Judiciário, com competência para revogar acórdãos do STF', 'B) Órgão de controle administrativo, financeiro e disciplinar do Poder Judiciário', 'C) Órgão consultivo do Congresso Nacional sobre assuntos judiciais', 'D) Tribunal Superior com jurisdição em todo o território nacional', 'E) Órgão vinculado ao Ministério da Justiça para supervisão judicial'], 'resposta': 'B', 'explicacao': 'O CNJ (art. 103-B, CF) é órgão do Poder Judiciário com atribuições de controle da atuação administrativa e financeira do Judiciário e do cumprimento dos deveres funcionais dos magistrados. NÃO tem competência jurisdicional — não julga processos, não reforma acórdãos. Pode expedir atos regulamentares, avocar processos disciplinares, e aplicar punições administrativas a magistrados.', 'dica': 'CNJ: controle ADMINISTRATIVO e DISCIPLINAR do Judiciário. NÃO tem competência jurisdicional — não julga processos. Presidido pelo Presidente do STF.', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2021},
        {'titulo': 'FGV/DPE-BA/2022 - Garantias dos Magistrados', 'enunciado': 'As garantias dos magistrados (art. 95, CF) têm como finalidade assegurar a independência do Poder Judiciário. São garantias dos magistrados:', 'opcoes': ['A) Vitaliciedade, inamovibilidade e irredutibilidade de subsídios', 'B) Vitaliciedade, imunidade penal absoluta e inamovibilidade', 'C) Vitaliciedade, imunidade tributária e irredutibilidade de vencimentos', 'D) Inamovibilidade, irredutibilidade de subsídios e imunidade material', 'E) Vitaliciedade, irredutibilidade de subsídios e imunidade formal'], 'resposta': 'A', 'explicacao': 'O art. 95, CF assegura aos magistrados: I - vitaliciedade (não podem ser demitidos, salvo por sentença judicial transitada em julgado — 1º e 2ª graus após 2 anos de estágio); II - inamovibilidade (salvo por interesse público, por deliberação do tribunal por voto da maioria absoluta de seus membros, com recurso ao CNJ); III - irredutibilidade de subsídio. Não há imunidade penal ou tributária especial para magistrados.', 'dica': 'Garantias dos magistrados: VI-INA-IRRE. Vitaliciedade (após 2 anos de estágio no 1º grau) + Inamovibilidade + Irredutibilidade de subsídios.', 'dificuldade': 'médio', 'fonte': 'FGV', 'ano': 2022},
    ],

    'Funções Essenciais à Justiça': [
        {'titulo': 'CESPE/PGR/2022 - Ministério Público', 'enunciado': 'O Ministério Público é instituição permanente, essencial à função jurisdicional do Estado (art. 127, CF). Sua finalidade constitucional é:', 'opcoes': ['A) Defender os interesses do Estado em juízo', 'B) Defender a ordem jurídica, o regime democrático e os interesses sociais e individuais indisponíveis', 'C) Representar judicialmente a União em matéria tributária', 'D) Controlar os atos do Poder Judiciário', 'E) Assessorar juridicamente os Poderes da República'], 'resposta': 'B', 'explicacao': 'O art. 127, caput, CF define a missão do MP: defender a ordem jurídica, o regime democrático e os interesses sociais e individuais indisponíveis. O MP não defende os interesses do Estado (isso é função da Advocacia Pública — AGU, PGE, PGM). Atua como fiscal da lei (custos legis) e como parte (dominus litis).', 'dica': 'MP: defender ordem jurídica + regime democrático + interesses sociais e individuais indisponíveis. NÃO é advogado do Estado (isso é a AGU/PGE/PGM).', 'dificuldade': 'fácil', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FCC/MPE-GO/2021 - Princípios do MP', 'enunciado': 'Os princípios institucionais do Ministério Público (art. 127, §1º, CF) são:', 'opcoes': ['A) Hierarquia, disciplina e subordinação ao Judiciário', 'B) Unidade, indivisibilidade e independência funcional', 'C) Legalidade, impessoalidade e moralidade', 'D) Independência, imparcialidade e publicidade', 'E) Unicidade, hierarquia e organização por ramos'], 'resposta': 'B', 'explicacao': 'O art. 127, §1º, CF estabelece os princípios institucionais do MP: unidade (o MP é um só, não se divide), indivisibilidade (seus membros podem substituir-se uns aos outros sem violação do princípio do promotor natural) e independência funcional (cada membro atua com total autonomia de convicção, sem subordinação hierárquica quanto ao mérito de suas manifestações).', 'dica': 'Princípios do MP: UI-IN-IF — Unidade, Indivisibilidade, Independência Funcional. Não há subordinação hierárquica quanto ao MÉRITO — só administrativamente.', 'dificuldade': 'médio', 'fonte': 'FCC', 'ano': 2021},
        {'titulo': 'CESPE/AGU/2022 - Advocacia-Geral da União', 'enunciado': 'A Advocacia-Geral da União (art. 131, CF) tem como função institucional:', 'opcoes': ['A) Fiscalizar a constitucionalidade das leis federais', 'B) Representar a União judicial e extrajudicialmente e prestar consultoria e assessoramento jurídico ao Poder Executivo', 'C) Defender os cidadãos hipossuficientes perante o Estado', 'D) Controlar a legalidade dos atos do MP', 'E) Acusar nos processos criminais de competência da Justiça Federal'], 'resposta': 'B', 'explicacao': 'A AGU (art. 131, CF) representa a União judicial e extrajudicialmente e presta consultoria e assessoramento jurídico ao Poder Executivo. O Advogado-Geral da União tem status de Ministro de Estado e é nomeado pelo Presidente da República. A AGU não acusa criminalmente (isso é função do MP).', 'dica': 'AGU: representa e defende a UNIÃO (judicial e extrajudicialmente) + consultoria jurídica ao Executivo. Diferente do MP (fiscal da lei) e da Defensoria (hipossuficientes).', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FGV/DPU/2022 - Defensoria Pública', 'enunciado': 'A Defensoria Pública (art. 134, CF) tem como missão:', 'opcoes': ['A) Defender o Estado em ações de improbidade administrativa', 'B) A orientação jurídica, a promoção dos direitos humanos e a defesa dos necessitados em todos os graus', 'C) Apenas a defesa criminal de réus sem advogado', 'D) Representar o MP nas causas em que este for parte', 'E) Controlar a constitucionalidade de atos normativos estaduais'], 'resposta': 'B', 'explicacao': 'O art. 134, CF define a Defensoria como "instituição permanente, essencial à função jurisdicional do Estado, incumbindo-lhe, como expressão e instrumento do regime democrático, fundamentalmente, a orientação jurídica, a promoção dos direitos humanos e a defesa, em todos os graus, judicial e extrajudicial, dos direitos individuais e coletivos, de forma integral e gratuita, aos necessitados". EC 80/2014 ampliou o conceito para incluir direitos coletivos.', 'dica': 'Defensoria Pública: orientação jurídica + promoção dos DH + defesa dos necessitados em TODOS OS GRAUS. EC 80/2014 incluiu defesa de direitos coletivos.', 'dificuldade': 'médio', 'fonte': 'FGV', 'ano': 2022},
    ],

    'Ordem Econômica e Social': [
        {'titulo': 'CESPE/TCE-RJ/2021 - Ordem Econômica', 'enunciado': 'A ordem econômica na CF/88 (art. 170) é fundada na valorização do trabalho humano e na livre iniciativa, tendo por fim assegurar a todos existência digna. Os princípios da ordem econômica incluem:', 'opcoes': ['A) Planificação central da economia pelo Estado', 'B) Proibição da propriedade privada dos meios de produção', 'C) Função social da propriedade e defesa do consumidor', 'D) Exclusividade do capital nacional nas atividades econômicas', 'E) Proibição de monopólios estatais'], 'resposta': 'C', 'explicacao': 'O art. 170, CF lista os princípios da ordem econômica: soberania nacional, propriedade privada, função social da propriedade, livre concorrência, defesa do consumidor, defesa do meio ambiente, redução das desigualdades regionais, busca do pleno emprego e tratamento favorecido para as empresas de pequeno porte. A função social da propriedade e a defesa do consumidor são princípios constitucionais expressos.', 'dica': 'Princípios da ordem econômica (art. 170): So-Pro-Fun-Li-De(consumidor)-De(ambiental)-Re-Bu-Tra. Fundamentos: valorização do trabalho + livre iniciativa.', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2021},
        {'titulo': 'FCC/TRT-15/2022 - Função Social da Propriedade Rural', 'enunciado': 'A propriedade rural cumpre sua função social (art. 186, CF) quando atende, simultaneamente, critérios. NÃO é requisito da função social da propriedade rural:', 'opcoes': ['A) Aproveitamento racional e adequado', 'B) Utilização adequada dos recursos naturais disponíveis', 'C) Preservação do meio ambiente', 'D) Observância das disposições que regulam as relações de trabalho', 'E) Pagamento regular dos impostos incidentes sobre a propriedade'], 'resposta': 'E', 'explicacao': 'O art. 186, CF: a função social da propriedade rural é cumprida quando a propriedade rural atende, simultaneamente, os seguintes requisitos: I - aproveitamento racional e adequado; II - utilização adequada dos recursos naturais disponíveis e preservação do meio ambiente; III - observância das disposições que regulam as relações de trabalho; IV - exploração que favoreça o bem-estar dos proprietários e dos trabalhadores. O pagamento de impostos NÃO está no rol.', 'dica': 'Função social da propriedade RURAL (art. 186): APRO-REC-REL-EXP. Aproveitamento racional, Recursos naturais, Relações de trabalho, Exploração favorável ao bem-estar. Imposto não está no rol.', 'dificuldade': 'médio', 'fonte': 'FCC', 'ano': 2022},
        {'titulo': 'CESPE/INSS/2022 - Direitos Sociais', 'enunciado': 'O art. 6º, CF/88 (com redação dada pela EC 90/2015 e EC 114/2021) estabelece como direitos sociais:', 'opcoes': ['A) Apenas educação, saúde e trabalho', 'B) Educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência social, proteção à maternidade e à infância, assistência aos desamparados e acesso à internet', 'C) Apenas os direitos de 2ª geração', 'D) Educação, saúde e seguridade social apenas', 'E) Educação, saúde, trabalho e moradia apenas'], 'resposta': 'B', 'explicacao': 'O art. 6º, CF (com alterações das EC 64/2010 que acrescentou alimentação; EC 90/2015 que acrescentou transporte; e EC 114/2021 que acrescentou acesso à internet): educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência social, proteção à maternidade e à infância, assistência aos desamparados e acesso à internet.', 'dica': 'Direitos sociais (art. 6º): E-S-Al-T-M-Tr-L-Se-P-Ma-As-Ac (edu, saúde, alim, trab, mor, transp, lazer, seg, prev, matern, assist, INTERNET — EC 114/2021).', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FGV/TRE-SP/2022 - Ordem Social', 'enunciado': 'A ordem social (Título VIII, CF) tem como base o primado do trabalho e como objetivo o bem-estar e a justiça sociais (art. 193, CF). O SUS — Sistema Único de Saúde — tem como diretrizes, entre outras:', 'opcoes': ['A) Centralização das ações e serviços de saúde na União', 'B) Descentralização, com direção única em cada esfera de governo, e atendimento integral', 'C) Privatização dos serviços de saúde como regra', 'D) Participação exclusiva do setor privado na gestão do SUS', 'E) Atendimento apenas dos contribuintes do sistema previdenciário'], 'resposta': 'B', 'explicacao': 'O art. 198, CF estabelece as diretrizes do SUS: I - descentralização, com direção única em cada esfera de governo; II - atendimento integral, com prioridade para as atividades preventivas, sem prejuízo dos serviços assistenciais; III - participação da comunidade. O SUS é financiado por recursos do orçamento da seguridade social (art. 198, §1º) e é de acesso universal e igualitário (art. 196).', 'dica': 'SUS: descentralização + direção única + atendimento integral + participação da comunidade. Acesso universal e igualitário. Financiado pela seguridade social.', 'dificuldade': 'médio', 'fonte': 'FGV', 'ano': 2022},
    ],

    'Controle de Constitucionalidade': [
        {'titulo': 'CESPE/STF/2022 - ADI', 'enunciado': 'A Ação Direta de Inconstitucionalidade (ADI) tem por objeto o controle abstrato de normas. São legitimados para propor ADI (art. 103, CF):', 'opcoes': ['A) Qualquer cidadão com pleno exercício dos direitos políticos', 'B) Apenas o Presidente da República e o PGR', 'C) O Presidente da República, as Mesas do Congresso e dos Legislativos estaduais, os Governadores, o PGR, os Conselhos Federais do OAB, os Partidos políticos com representação no CN e as confederações sindicais ou entidades de classe de âmbito nacional', 'D) Qualquer partido político registrado no TSE', 'E) O STJ, quando identificar inconstitucionalidade de lei federal'], 'resposta': 'C', 'explicacao': 'O art. 103, CF lista taxativamente os legitimados para propor ADI, ADC, ADPF: I - Presidente da República; II - Mesa do Senado Federal; III - Mesa da Câmara dos Deputados; IV - Mesa de Assembleia Legislativa ou da Câmara Legislativa do DF; V - Governador de Estado ou do DF; VI - Procurador-Geral da República; VII - Conselho Federal da OAB; VIII - partido político com representação no CN; IX - confederação sindical ou entidade de classe de âmbito nacional.', 'dica': 'Legitimados ADI (art. 103): PRE-ME(Senado)-ME(Câmara)-ME(estadual)-GOV-PGR-OAB-PAR-CON. 9 legitimados. Universais × especiais (devem comprovar pertinência temática).', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FCC/TRF-2/2022 - Efeitos do Controle', 'enunciado': 'A decisão do STF em ADI que declara a inconstitucionalidade de uma lei produz efeitos:', 'opcoes': ['A) Ex nunc (a partir da decisão) e inter partes', 'B) Ex tunc (retroativos à origem da lei) e erga omnes, com efeito vinculante', 'C) Ex nunc e erga omnes, sem efeito vinculante', 'D) Apenas para as partes do processo, sem efeito vinculante', 'E) Retroativos apenas para os processos em andamento'], 'resposta': 'B', 'explicacao': 'A decisão do STF em controle concentrado abstrato (ADI, ADC, ADPF) produz: (1) efeito ex tunc — retroage à data da criação da norma inconstitucional; (2) efeito erga omnes — vale para todos; (3) efeito vinculante — vincula os demais órgãos do Judiciário e a Administração Pública. O STF pode, excepcionalmente, modular os efeitos para o futuro (ex nunc) ou a partir de data determinada, por razões de segurança jurídica ou excepcional interesse social (art. 27, Lei 9.868/99).', 'dica': 'Controle concentrado: ex tunc + erga omnes + efeito vinculante. Modulação temporal: STF pode restringir os efeitos retroativos por segurança jurídica (2/3 dos membros).', 'dificuldade': 'médio', 'fonte': 'FCC', 'ano': 2022},
        {'titulo': 'CESPE/MPF/2022 - ADPF', 'enunciado': 'A Arguição de Descumprimento de Preceito Fundamental (ADPF) é instrumento de controle concentrado de constitucionalidade cabível, entre outros casos, para:', 'opcoes': ['A) Questionar a constitucionalidade de emendas constitucionais', 'B) Evitar ou reparar lesão a preceito fundamental resultante de ato do Poder Público, inclusive quando for relevante o fundamento da controvérsia constitucional sobre lei ou ato normativo federal, estadual ou municipal, anteriores à CF', 'C) Substituir a ADI quando esta não for admitida', 'D) Questionar apenas leis municipais', 'E) Criar novos direitos fundamentais não previstos na CF'], 'resposta': 'B', 'explicacao': 'A ADPF (Lei 9.882/99) tem caráter residual (subsidiário) em relação à ADI e à ADC. É admissível quando: a) evitar ou reparar lesão a preceito fundamental resultante de ato do Poder Público; b) quando for relevante o fundamento da controvérsia constitucional sobre lei ou ato normativo federal, estadual ou municipal, inclusive anteriores à Constituição (pré-constitucionais). A ADI não alcança leis pré-constitucionais — para isso usa-se a ADPF.', 'dica': 'ADPF: residual (subsidiária). Alcança normas pré-constitucionais e municipais (que ADI não alcança). Preceito fundamental = DFs, separação de poderes, forma federativa.', 'dificuldade': 'difícil', 'fonte': 'CESPE', 'ano': 2022},
        {'titulo': 'FGV/TRE-RN/2022 - Controle Difuso', 'enunciado': 'No controle difuso de constitucionalidade, a declaração de inconstitucionalidade:', 'opcoes': ['A) Tem efeito erga omnes imediato, como no controle concentrado', 'B) Se dá incidentalmente, com eficácia inter partes, podendo ter efeito erga omnes apenas se o Senado suspender a execução da norma', 'C) Só pode ser feita pelo STF', 'D) Invalida a norma com efeito ex nunc', 'E) É feita por qualquer tribunal ou juiz sem necessidade de remeter ao plenário'], 'resposta': 'B', 'explicacao': 'No controle difuso (concreto, incidental), qualquer juiz ou tribunal pode declarar inconstitucionalidade como questão incidental. A declaração produz efeitos apenas inter partes (entre as partes do processo). Para dar efeito erga omnes, o Senado pode, discricionariamente, suspender a execução da norma declarada inconstitucional (art. 52, X, CF). No STF, há a tese da "abstrativização" do controle difuso (STF entende que, mesmo no controle difuso, suas decisões têm efeitos ampliados).', 'dica': 'Controle difuso: incidental, inter partes. Para efeito erga omnes: Senado suspende (art. 52, X) — discricionário. STF tem abstrativizado o controle difuso.', 'dificuldade': 'difícil', 'fonte': 'FGV', 'ano': 2022},
        {'titulo': 'CESPE/TJ-ES/2022 - Súmula Vinculante', 'enunciado': 'A súmula vinculante (art. 103-A, CF) pode ser editada pelo STF, de ofício ou por provocação, mediante decisão de 2/3 de seus membros, após reiteradas decisões sobre matéria constitucional. Tem efeito vinculante em relação:', 'opcoes': ['A) A todos os órgãos do Poder Judiciário e ao Poder Executivo, mas não ao Legislativo', 'B) Apenas ao STJ e aos Tribunais de Justiça', 'C) A todos os órgãos do Poder Judiciário e à administração pública direta e indireta, nas esferas federal, estadual e municipal', 'D) Ao Poder Judiciário apenas, excluída a Administração Pública', 'E) Ao Poder Judiciário federal apenas'], 'resposta': 'C', 'explicacao': 'O art. 103-A, CF: a súmula vinculante terá efeito vinculante em relação aos demais órgãos do Poder Judiciário e à administração pública direta e indireta, nas esferas federal, estadual e municipal. Atenção: a súmula vinculante NÃO vincula o STF (pode superá-la), nem o Poder Legislativo (este age com liberdade para criar novas leis, inclusive contrariando a súmula).', 'dica': 'Súmula vinculante: vincula Judiciário + Adm. Pública (todas as esferas). NÃO vincula: o próprio STF e o Poder Legislativo.', 'dificuldade': 'médio', 'fonte': 'CESPE', 'ano': 2022},
    ],
}
